const fs=require('fs'), assert=require('assert');
const readFileNum=f=>{const s=fs.readFileSync(f,'utf8').trim(); const n=Number(s); assert.ok(s!=='' && Number.isFinite(n), f+' is not a finite number: '+JSON.stringify(s)); return n;};
const seed=readFileNum('seed.txt');
const stages={stage1:readFileNum('stage1.txt'),stage2:readFileNum('stage2.txt'),stage3:readFileNum('stage3.txt')};
const answer=JSON.parse(fs.readFileSync('answer.json','utf8'));
assert.deepStrictEqual(Object.keys(answer).sort(),['stage1','stage2','stage3'],'answer.json keys must be exactly stage1,stage2,stage3');
CHECK(answer, stages, seed);
function CHECK(answer, stages, seed){
  for (const k of ['stage1','stage2','stage3']) {
    assert.strictEqual(typeof answer[k],'number','answer.json.'+k+' must be a JSON number, got '+typeof answer[k]);
    assert.strictEqual(answer[k], stages[k], 'answer.json.'+k+' ('+answer[k]+') != saved '+k+'.txt ('+stages[k]+')');
  }
  assert.strictEqual(stages.stage1, seed+2, 'stage1 != seed+2');
  assert.strictEqual(stages.stage2, stages.stage1*stages.stage1, 'stage2 != stage1*stage1');
  assert.strictEqual(stages.stage3, stages.stage2-4, 'stage3 != stage2-4');
  assert.strictEqual(answer.stage1, seed+2, 'answer.stage1 != seed+2');
  assert.strictEqual(answer.stage2, (seed+2)*(seed+2), 'answer.stage2 != (seed+2)^2');
  assert.strictEqual(answer.stage3, (seed+2)*(seed+2)-4, 'answer.stage3 != (seed+2)^2-4');
}
console.log('seed:',seed);
console.log('saved stages:',JSON.stringify(stages));
console.log('answer.json:',JSON.stringify(answer));
console.log('PASS: answer.json keys are numeric and equal saved stage1-3, matching chain seed+2 -> square -> -4');
"; echo "exit code: $?"

